begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "29208a42-335a-5ee6-a6cb-b5860cb0c7c4", "feature_slug": "tiers", "title": "Function Categories & Architecture", "content": "### 🎯 CORE FUNCTIONS (Business Logic Orchestrators)\n\n#### `evaluate_user_tier_status(user_id, merchant_id, evaluation_date)`\n**Purpose**: Master tier evaluation engine that determines tier changes - **used for BOTH upgrade and maintain evaluations**  \n**Category**: Core Business Logic Orchestrator  \n**Returns**: JSONB with evaluation results, recommendations, **and upgrade timing information**\n**Fixed in v4.1**: Now properly respects window_type (previously ignored, causing all evaluations to use rolling windows)\n\n**Return Fields** (key fields):\n| Field | Type | Description |\n|-------|------|-------------|\n| `recommended_action` | text | ''upgrade'', ''downgrade'', ''maintain'', or ''assign_entry'' |\n| `recommended_tier_id` | uuid | Target tier for upgrade/downgrade |\n| `to_tier_ranking` | smallint | Ranking of recommended tier |\n| `upgrade_timing` | text | Delay type: NULL, ''end_of_month'', ''fixed_date'', ''rolling_days'' |\n| `upgrade_timing_value` | text | Configuration value for timing |\n| `effective_at` | date | Calculated effective date for delayed upgrades |\n\n**Unified Evaluation for Upgrade and Maintain**:\n- Same function handles both condition types\n- For upgrades: Evaluates against higher tier conditions directly from source tables\n- For maintains: Called when tier_evaluation_tracking indicates deadline reached\n- **Window calculation**: Uses `calculate_tier_window_dates()` to properly respect window_type (fixed in v4.1)\n- Returns upgrade timing configuration when upgrade is recommended\n\n**Detailed Logic Flow**:\n1. **Current Tier Lookup**: Retrieves current tier from `user_accounts` joined with `tier_master`\n2. **Entry Tier Assignment**: If no current tier, finds and assigns entry tier (`entry_tier = true`)\n3. **Metric Calculation**: Calculates all metrics for appropriate windows based on condition configuration\n4. **Maintenance Evaluation**: Checks all maintain conditions for current tier (if deadline reached)\n5. **Upgrade Evaluation**: Identifies best upgrade opportunities from higher tiers\n6. **Decision Logic**: Determines recommended action (upgrade/downgrade/maintain/assign_entry)\n7. **Timing Calculation** (NEW): If upgrade recommended, calculates `effective_at` using `calculate_upgrade_effective_date()`\n\n**Key Business Rules Implementation**:\n```sql\n-- Points/Tickets (wallet_ledger evaluation)\nWHERE currency = ''points'' \n  AND transaction_type = ''earn''  -- Excludes burn transactions\n  AND created_at >= evaluation_date - INTERVAL ''6 months''\n\n-- Sales (purchase_ledger evaluation with credit/debit handling)\nSUM(CASE \n  WHEN record_type = ''credit'' THEN final_amount\n  WHEN record_type = ''debit'' THEN -ABS(final_amount)\nEND)\n\n-- Orders (purchase_ledger count excluding refunds)\nCOUNT(*) WHERE final_amount > 0  -- Don''t count refunds as orders\n```\n\n#### `ensure_tier_progress(user_id, merchant_id)`\n**Purpose**: Progress management and tier change execution  \n**Category**: Core Business Logic Orchestrator  \n**Returns**: void (performs updates)\n\n**Comprehensive Responsibilities**:\n1. **Current State Assessment**: Gets current tier from `user_accounts`\n2. **Tier Evaluation**: Calls `evaluate_user_tier_status` for current assessment\n3. **Next Tier Calculation**: Determines next achievable tier based on ranking\n4. **Progress Updates**: Updates `tier_progress` with current progress percentages\n5. **Tier Change Execution**: If recommended tier differs from current tier\n6. **Maintenance Deadline Setting** (NEW): On upgrade, calculates and stores maintenance deadline in `tier_evaluation_tracking`\n7. **Progress Calculation Logic**:\n   ```sql\n   -- Upgrade Progress\n   upgrade_progress = (current_points_6mo / upgrade_threshold) * 100\n   \n   -- Maintenance Progress (can exceed 100%)\n   maintain_progress = (current_points_12mo / maintenance_threshold) * 100\n   ```\n\n**Critical for Maintenance**: When user upgrades, this function:\n- Calls `calculate_maintain_deadline()` to determine when maintenance evaluation should occur\n- Stores deadline in `tier_evaluation_tracking` for cron job processing\n- Updates `tier_progress.maintain_deadline` for display purposes\n\n#### `calculate_tier_metric_value(user_id, metric, window_start, window_end, user_type)`\n**Purpose**: Individual metric calculation engine  \n**Category**: Core Calculation Engine  \n**Returns**: NUMERIC value for specified metric\n\n**Metric-Specific Implementation Logic**:\n\n**Points/Tickets Calculation**:\n```sql\nWHEN p_metric IN (''points'', ''ticket'') THEN\n  SELECT COALESCE(SUM(amount), 0)\n  FROM wallet_ledger\n  WHERE user_id = p_user_id\n    AND currency = p_metric\n    AND transaction_type = ''earn''  -- CRITICAL: Only earn transactions\n    AND created_at >= p_window_start\n    AND created_at < p_window_end + INTERVAL ''1 day''\n```\n\n**Sales Calculation**:\n```sql\nWHEN p_metric = ''sales'' THEN\n  SELECT COALESCE(SUM(final_amount), 0)  -- Handles negative amounts for refunds\n  FROM purchase_ledger\n  WHERE merchant_id = p_merchant_id\n    AND CASE \n      WHEN p_user_type = ''buyer'' THEN user_id = p_user_id\n      WHEN p_user_type = ''seller'' THEN seller_id = p_user_id\n    END\n    AND created_at >= p_window_start\n    AND created_at < p_window_end + INTERVAL ''1 day''\n```\n\n### 🖥️ RENDER CONSUMER (Upgrade Processing)\n\n#### `crm-event-processors` Service\n**Purpose**: Kafka consumer for real-time tier evaluation and upgrade orchestration  \n**Category**: Event Processor  \n**Platform**: Render Web Service  \n**Runtime**: Node.js + TypeScript\n\n**Key Components**:\n\n| File | Purpose |\n|------|---------|\n| `src/consumers/tier-consumer.ts` | Kafka consumer for `tier_change_ledger` / `wallet_ledger` / `purchase_ledger` events; calls `process_tier_event` once per event |\n| `src/clients/kafka.ts` | Kafka client + Debezium parsing |\n| `src/clients/supabase.ts` | Supabase service-role client; `processTierEvent` helper |\n| `src/clients/redis.ts` | Redis deduplication only |\n\n**Processing Flow** (v5.0 — one Postgres call per event):\n\n```typescript\nconst debezium = parseDebeziumMessage(message.value);\nconst { user_id: userId, merchant_id: merchantId } = extractIds(debezium);\n\n// 5-minute Redis dedup window (dedup only, not pending state)\nif (await isDuplicate(tierDedupKey(userId, merchantId), 300)) return;\n\n// Single atomic call — Postgres decides immediate / delayed / maintain / downgrade\nconst { data, error } = await supabase.rpc(''process_tier_event'', {\n  p_user_id: userId,\n  p_merchant_id: merchantId,\n});\nif (error) throw error;\n\nlogger.info({ userId, merchantId, action: data.action }, ''tier event processed'');\n```\n\n**Environment Variables**:\n\n| Variable | Purpose |\n|----------|---------|\n| `KAFKA_BOOTSTRAP_SERVERS` | Confluent Cloud bootstrap servers |\n| `KAFKA_API_KEY` | Confluent API key |\n| `KAFKA_API_SECRET` | Confluent API secret |\n| `SUPABASE_URL` | Supabase project URL |\n| `SUPABASE_SERVICE_ROLE_KEY` | Service role key for RPC calls |\n| `REDIS_URL` | Render Redis connection string |\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Tier.md#L1179 Function Categories & Architecture", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "68176b02c88f324a8c30350d33d3618f464e4703e1a640518fc805a0f72d8bc3", "truncated": true}, "is_active": true}, {"id": "f27be1b5-7f1d-53fd-b6f6-274adc554177", "feature_slug": "tiers", "title": "Core Tables and Structure", "content": "### 1. tier_master Table\nThis table defines the available tiers for each merchant. Key fields include:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier for the tier |\n| `merchant_id` | uuid | Links to the merchant who owns this tier |\n| `tier_name` | text | Display name of the tier (e.g., \"Gold\", \"Platinum\") |\n| `user_type` | enum | Optional user type filter (''buyer'' or ''seller''). Works independently with persona assignments |\n| `persona_id` | uuid | Legacy compatibility mirror of the first assigned persona. Multi-persona matching uses `tier_persona_assignments`; do not use this column as source of truth |\n| `ranking` | smallint | Numerical rank used for tier hierarchy (higher rank = higher tier) |\n| `entry_tier` | boolean | Indicates if this is the default tier for new users. Only one entry tier allowed per merchant/user_type/persona combination |\n| `burn_rate` | numeric | **NEW v4.3**: Points-to-currency conversion rate for direct point-to-discount. e.g., `0.50` means 1 point = 0.50 THB. NULL means feature not enabled for this tier |\n| `icon` | text | Image URL for the tier icon (e.g., `\"https://project.supabase.co/storage/v1/object/public/images/gold-tier.svg\"`) |\n| `color` | text | Hex color for tier accent (e.g., `\"#FFD700\"` for gold) |\n| `benefits` | jsonb | **NEW v4.4**: Array of benefit display lines. See [Benefits JSONB Schema](#benefits-jsonb-schema) |\n| `card_design` | jsonb | **NEW v4.4**: Optional JSONB for advanced card styling (background image, gradient, etc.) |\n| `created_at` | timestamptz | Timestamp of tier creation |\n\n### 2. tier_persona_assignments Table\nThis table assigns one tier to zero, one, or many personas.\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique assignment identifier |\n| `merchant_id` | uuid | Merchant isolation key |\n| `tier_id` | uuid | References `tier_master.id`; cascades when a tier is deleted |\n| `persona_id` | uuid | References `persona_master.id`; cascades when a persona is deleted |\n| `created_at` | timestamptz | Timestamp of assignment creation |\n\n**Semantics**:\n- No rows for a tier in `tier_persona_assignments` = tier applies to all personas.\n- One or more rows = tier applies only to users whose `user_accounts.persona_id` is in that set.\n- `tier_master.persona_id` is kept only for legacy reads and mirrors one assigned persona.\n\n### 3. tier_conditions Table\nThis table defines the conditions required to upgrade to or maintain each tier. A single tier can have multiple conditions, providing different paths to achieve the same tier. Key fields include:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | bigint | Unique identifier for the condition |\n| `merchant_id` | uuid | Links to the merchant |\n| `tier_id` | uuid | References the tier in tier_master this condition applies to |\n| `condition_type` | enum | Either ''upgrade'' (to achieve tier) or ''maintain'' (to keep tier) |\n| `metric` | enum | What to measure - ''points'', ''ticket'', ''sales'', or ''orders'' |\n| `amount` | numeric | Target amount required for the metric |\n| `window_months` | smallint | Duration of the evaluation window in months |\n| `window_type` | enum | How to calculate the window: ''calendar_month'', ''calendar_quarter'', ''rolling'', ''fixed_period'', or ''anniversary'' |\n| `window_start` | varchar | For fixed_period only: defines start date (e.g., \"01-01\", \"03-15\"). NULL for calendar/rolling/anniversary types |\n| `window_start_field` | enum | For anniversary type only: specifies which date field from user_accounts to use (e.g., ''create_date'') |\n| `frequency` | enum | When to execute tier calculations (see detailed explanation below) |\n| `upgrade_evaluation_timing` | text | **For upgrade conditions only**: When to apply the upgrade - NULL/''immediate'', ''end_of_month'', ''fixed_date'', or ''rolling_days'' |\n| `upgrade_evaluation_value` | text | **For upgrade conditions only**: Configuration value for timing - NULL for immediate/end_of_month, ''MM-DD'' for fixed_date, or number of days for rolling_days |\n| `active_status` | boolean | Whether this condition is currently active |\n| `created_at` | timestamptz | Timestamp of condition creation |\n\n#### Upgrade Timing Configuration\n\nThe `upgrade_evaluation_timing` field controls when a tier upgrade takes effect after a user qualifies:\n\n| Timing | Value Example | Behavior |\n|--------|---------------|----------|\n| NULL or ''immediate'' | NULL | Upgrade applied immediately when user qualifies |\n| ''end_of_month'' | NULL | Upgrade scheduled for end of current month |\n| ''fixed_date'' | ''01-01'' (MM-DD) | Upgrade scheduled for next occurrence of specified date |\n| ''rolling_days'' | ''7'' | Upgrade scheduled for X days after qualification |\n\n**Important (v4.5)**: When an upgrade is delayed (not immediate), the system:\n1. Inserts/updates a row in `tier_pending_upgrades` (one row per user — UPSERT supersedes any prior pending).\n2. The `tier-daily-batch` Render Cron Job runs every day at 02:00 UTC and (as STEP 1) calls `tier_apply_due_pending_upgrades()` before the maintain pass.\n3. For each row where `effective_at <= today`, the cron **re-runs** `evaluate_user_tier_status` to confirm the user still qualifies — and applies whatever the user qualifies for now (which can be higher than the originally pending tier).\n4. If the user no longer qualifies, the pending row is deleted and `tier_progress` is refreshed.\n5. A new earn event before the effective date will overwrite the pending row (newer pending supersedes older).\n\n### 4. tier_progress Table\nThis table maintains one record per user showing their current tier status and progress toward upgrades or maintenance requirements. **This is purely for display purposes** - actual tier evaluation state is tracked in `tier_evaluation_tracking`. Fields include:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier |\n| `user_id` | uuid | References auth.users |\n| `merchant_id` | uuid | Links to the merchant |\n| `current_tier_id` | uuid | User''s current tier from tier_master |\n| `next_tier_id` | uuid | Next achievable tier |\n| `upgrade_metric_needed` | enum | Which metric is being tracked for upgrade |\n| `upgrade_progress_percent` | numeric | Percentage progress toward upgrade (always shows highest progress among multiple conditions) |\n| `upgrade_deadline` | date | Date by which upgrade conditions must be met |\n| `maintain_metric_needed` | enum | Which metric is being tracked for maintenance |\n| `maintain_progress` | numeric | Current progress toward maintenance requirement |\n| `maintain_deadline` | date | Date by which maintenance conditions must be met (copied from tier_evaluation_tracking) |\n| `created_at` | timestamptz | Timestamp of record creation |\n\n### 4a. Pending Upgrade State (`tier_pending_upgrades`, v4.5)\n\nDelayed upgrades are persisted in a single table and applied by a daily Postgres cron. No Inngest. No QStash. The Render consumer never sleeps.\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Tier.md#L50 Core Tables and Structure", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ea9f96c26775cbae4c4f199b33f37d479f278545e7dbb4299062a87db26d2191", "truncated": true}, "is_active": true}, {"id": "7d56c8c1-6190-5d34-9431-ae16352ba960", "feature_slug": "tiers", "title": "2. Key Concepts", "content": "**Tier** — A named membership level with a ranking that determines its position in the hierarchy. Example: \"Gold\" at ranking 2 sits above \"Silver\" at ranking 1.\n\n**Ranking** — A numeric value (smallint) that orders tiers from lowest to highest. Higher ranking = higher tier. The system uses ranking to determine upgrade targets and downgrade destinations.\n\n**Entry Tier** — The tier automatically assigned to new members on signup. Exactly one tier per user_type/persona combination should be marked as entry tier. Example: \"Bronze\" is the entry tier for buyers.\n\n**Upgrade Condition** — A rule that qualifies a member for a higher tier. Each condition specifies a metric, a target amount, and a time window. Multiple upgrade conditions on the same tier use OR logic — meeting any one condition triggers the upgrade. Example: \"Earn 500 points in 6 months\" OR \"Spend ฿10,000 in 12 months\" → either qualifies for Gold.\n\n**Maintain Condition** — A rule that must be met to keep the current tier. When a maintain deadline arrives and the member fails all maintain conditions, they are downgraded. Example: \"Maintain 200 points in 12 months to stay Gold.\"\n\n**Metric** — The measurement unit for conditions. Four types: `points` (points earned), `ticket` (tickets earned), `sales` (purchase amount), `orders` (number of completed purchases).\n\n**Window Type** — How the evaluation period is calculated. Five types:\n\n- `rolling` — Look back N months from evaluation date (e.g., \"last 6 months\")\n- `fixed_period` — From a specific MM-DD start date for N months (e.g., \"Jan 1 to Jun 30 every year\")\n- `anniversary` — From the member''s signup anniversary for N months\n- `calendar_month` — Current calendar month (1st to last day)\n- `calendar_quarter` — Current calendar quarter (Q1=Jan-Mar, Q2=Apr-Jun, Q3=Jul-Sep, Q4=Oct-Dec)\n\n**Evaluation Frequency** — How often conditions are checked: `realtime` (on every qualifying transaction), `daily` (batch), `monthly` (batch), `period_end` (at window expiration).\n\n**Burn Rate** — A numeric value on a tier that converts points to monetary discount at checkout. Example: burn_rate = 0.5 means 1 point = ฿0.50 discount. NULL means burn rate is disabled for that tier.\n\n**Persona-Based Segmentation** — Tiers can be scoped to a specific persona via `persona_id`. This creates parallel tier ladders — a \"Buyer\" persona has its own Bronze/Silver/Gold, separate from a \"Seller\" persona''s tiers. NULL persona = universal (applies to all members regardless of persona).\n\n**Tier Progress** — A per-user record tracking: current tier, next upgrade target, percentage progress toward upgrade, metric needed, upgrade deadline, and maintain progress/deadline.\n\n**Tier Change Ledger** — Append-only audit log of every tier change. Records the change type (`initial`, `upgrade`, `downgrade`, `manual`, `scheduled`), from/to tier, reason, and timestamp.\n\n**Tier Locking** — Not yet implemented in the live schema. Reserved for future use where merchants can lock a member''s tier to prevent automatic downgrades for a specified period.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/tiers.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "62ecf8c97fb979f7e77ce1fc3d9bb16d6956acd63b997757a83204d00551b102", "truncated": false}, "is_active": true}, {"id": "f02164e8-4a36-5584-9267-5cec220c0f2b", "feature_slug": "tiers", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch**: \"Tiers create a visible loyalty ladder for your members. As they shop more, they automatically level up and unlock better benefits — better point-to-discount rates, exclusive rewards, and recognition. You control the rules: how many points or how much spending gets them to each level, and what happens if they don''t keep up.\"\n\n**Top 5 support questions:**\n\n\n| Question                                     | Answer                                                                                                                                                                              |\n| -------------------------------------------- | ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| \"Member didn''t upgrade after a big purchase\" | Check the upgrade condition''s window type and period — the purchase may fall outside the evaluation window. Also verify the condition''s metric matches (points vs sales vs orders). |\n| \"Member was downgraded unexpectedly\"         | The maintain deadline was reached and they didn''t meet the maintain conditions. Check `tier_change_ledger` for the exact reason and `tier_evaluation_tracking` for the deadline.    |\n| \"New member has no tier\"                     | Entry tier may not be configured for that member''s user_type/persona combination. Check `tier_master` for an entry tier matching their profile.                                     |\n| \"Burn rate shows 0 at checkout\"              | The member''s current tier has `burn_rate = NULL`. Only tiers with a numeric burn rate enable the discount feature.                                                                  |\n| \"Tier progress shows wrong percentage\"       | Progress is calculated from the best single upgrade condition path. If multiple conditions exist, the system picks the one with highest progress — not an aggregate.                |\n\n\n**Bug vs misconfiguration**: If tier changes appear in the ledger but the member app doesn''t reflect them → likely a UI cache issue. If no ledger entry exists when it should → check evaluation tracking status and condition windows.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/tiers.md#L189 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4f2d1607c2596fe7dca70bfc00420cbc7df675b9da92d7e1504fd5524d788471", "truncated": false}, "is_active": true}, {"id": "70fbf24d-b03e-547c-9105-227e4494ca99", "feature_slug": "tiers", "title": "1. Overview", "content": "Tiers rank members into levels based on their activity — purchases, points earned, or order count. A merchant defines a ladder of tiers (e.g., Silver → Gold → Platinum), sets conditions for upgrading and maintaining each level, and attaches benefits like burn-rate discounts or exclusive reward eligibility. Members progress automatically as the system evaluates their metrics against the configured conditions.\n\nFor merchants, tiers solve the segmentation problem: instead of treating all members equally, tiers let them reward high-value customers with better pricing, exclusive access, and recognition — creating a visible incentive to spend more. The system handles the full lifecycle: automatic entry-tier assignment on signup, real-time upgrade evaluation when transactions land, periodic maintain/downgrade checks on configurable schedules, and a progress tracker that shows members exactly how close they are to the next level.\n\nKey differentiators: (1) **five evaluation window types** — rolling, fixed period, anniversary, calendar month, and calendar quarter — giving merchants flexible measurement periods; (2) **persona-based tier segmentation** — separate tier ladders per persona (e.g., \"Buyer\" tiers vs \"Seller\" tiers); (3) **OR-logic upgrade paths** — any single condition qualifying is sufficient for upgrade, allowing multiple independent routes to the same tier; (4) **burn-rate per tier** — each tier can define a points-to-monetary-discount conversion rate used at checkout.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/tiers.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "af2313a7995274a7e5037c6b22420ca1f92b018a98b031e97441bb1ce5d5c9ff", "truncated": false}, "is_active": true}, {"id": "9de29ebf-1eb8-55b7-ac56-1ecb97e5c149", "feature_slug": "tiers", "title": "8. Related Features", "content": "| Feature              | Connection to Tiers                                                                                                                                               |\n| -------------------- | ----------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| Currency             | Points and tickets earned are metrics for tier conditions. Burn rate converts points to checkout discount. See Currency guide.                                    |\n| Rewards              | Reward eligibility can be tier-gated; dynamic pricing can vary by tier. See Rewards guide.                                                                        |\n| Tag & Persona        | Persona determines which tier ladder applies. User type (buyer/seller) partitions tiers. See `Tag_and_Persona.md`.                                                |\n| Purchase Transaction | Completed purchases (`status=''completed''`) trigger tier upgrade evaluation via CDC. Sales amount and order count are tier metrics. See `Purchase_Transaction.md`. |\n| Mission              | Missions can use tier as an eligibility filter. Tier upgrades don''t directly trigger missions. See `Mission.md`.                                                  |\n| Activity Earning     | Activity-earned points/tickets contribute to tier metrics. See `Activity_Based_Earning.md`.                                                                       |\n| Translation          | Tier names and benefits support multi-language via the translation system. See `Translation_System.md`.                                                           |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/tiers.md#L299 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6576ab0b3c087313c680cb5ef7844614b7b6a045dc91725b2e5a6451bac3ca3f", "truncated": false}, "is_active": true}, {"id": "c0215400-ae13-5e7b-b20c-07b133680d48", "feature_slug": "tiers", "title": "Automation & Scheduling Architecture (v5.0)", "content": "### Real-Time Path (CDC → Render → Postgres)\n\n```mermaid\nsequenceDiagram\n    participant DB as PostgreSQL\n    participant CDC as Confluent CDC\n    participant Kafka as Kafka Topic\n    participant Consumer as TierConsumer (Render)\n    participant Redis as Redis Dedup\n\n    DB->>CDC: INSERT into wallet_ledger / purchase_ledger\n    CDC->>Kafka: CDC event\n    Kafka->>Consumer: Consume\n    Consumer->>Redis: tier:dedup:{user}:{merchant} (5-min TTL)\n    alt duplicate within window\n        Redis-->>Consumer: hit -> skip\n    else first event in window\n        Consumer->>DB: process_tier_event(user, merchant)\n        Note over DB: Inside one transaction:<br/>evaluate_user_tier_status<br/>+ apply_tier_upgrade OR<br/>UPSERT tier_pending_upgrades OR<br/>refresh tier_progress\n        DB-->>Consumer: { action: ''upgrade_immediate'' | ''upgrade_pending'' | ''maintain'' | ''downgrade'' }\n    end\n```\n\n**Deduplication**: Redis 5-min TTL keyed `tier:dedup:{user_id}:{merchant_id}`. Multiple rapid events for the same user collapse into one Postgres call.\n\n### Daily Tier Batch (single Render Cron Job)\n\nThe two formerly-independent batch jobs (apply-pending-daily, maintain-daily) are now run in sequence inside one Render Cron Job. Order is intentional: STEP 1 applies due delayed upgrades first so STEP 2''s maintain evaluations see the post-apply state.\n\n```mermaid\nsequenceDiagram\n    participant RenderCron as Render Cron Job<br/>tier-daily-batch\n    participant Job as src/jobs/tier-daily-batch.ts\n    participant DB as PostgreSQL\n\n    Note over RenderCron: 02:00 UTC daily\n    RenderCron->>Job: spawn one-shot Node container\n\n    Note over Job,DB: STEP 1 — apply due pending upgrades\n    Job->>DB: tier_apply_due_pending_upgrades()\n    DB->>DB: For each row where effective_at <= today,<br/>re-run evaluate_user_tier_status\n    alt still qualifies\n        DB->>DB: apply_tier_upgrade(... current best tier ...)\n        Note over DB: apply_tier_upgrade clears the pending row\n    else no longer qualifies\n        DB->>DB: DELETE tier_pending_upgrades row + ensure_tier_progress\n    end\n    DB-->>Job: { applied, cancelled, skipped, run_at }\n\n    Note over Job,DB: STEP 2 — maintain / downgrade batch\n    Job->>DB: SELECT id, name FROM merchant_master ORDER BY id\n    DB-->>Job: 99 merchants\n    loop Each merchant (sequential)\n        Job->>DB: get_tier_evaluation_chunks(merchant, 200, today)\n        DB-->>Job: chunk plan (offset/limit per chunk)\n        Note over Job: 10-way parallel via p-limit\n        loop Each chunk (parallel)\n            Job->>DB: evaluate_and_apply_chunk(merchant, offset, limit, today)\n            Note over DB: Per-user: evaluate_user_tier_status,<br/>apply_tier_upgrade if needed,<br/>refresh tier_progress\n            DB-->>Job: TABLE rows (one per user)\n        end\n    end\n    Job->>RenderCron: stdout summary, exit 0 (or 1 if any chunk or STEP 1 failed)\n```\n\nReal-time path notes:\n- A maintain/downgrade event arriving on the consumer between when a pending row is queued and the next 02:00 UTC run deletes the pending row immediately.\n- A new qualifying earn event UPSERTs a fresh pending row, automatically superseding the older one.\n- Per-chunk failures inside STEP 2 are counted into `chunks_failed` and logged with merchant + chunk_index. STEP 1 failure is logged but does not abort STEP 2 — they''re independent decisions.\n\n### Cron Jobs (Tier)\n\n| Job | Where | Schedule | Purpose | Implementation |\n|---|---|---|---|---|\n| `tier-daily-batch` | Render Cron Job | `0 2 * * *` (02:00 UTC) | STEP 1: apply due delayed upgrades. STEP 2: maintain checks + downgrades for users past their `maintain_deadline`. | `npm run job:tier-daily-batch` (in `Rocket-CRM/crm-event-processors`) |\n\n**Key Architecture Points (v5.0)**\n- **Upgrades**: Render consumer → `process_tier_event` (immediate) or → `tier_pending_upgrades` row (delayed, applied by `tier-daily-batch` STEP 1).\n- **Maintains/Downgrades**: Render Cron Job `tier-daily-batch` STEP 2 only. The CDC path never writes a downgrade.\n- **Deduplication**: Redis 5-min TTL on the consumer side; chunk-level offset/limit on the batch side.\n- **Pending state**: `tier_pending_upgrades` Postgres table with a `(user_id, merchant_id)` unique constraint. No external workflow engine.\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Tier.md#L1627 Automation & Scheduling Architecture (v5.0)", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c62c57d9489780b913a211be8fffdbb6d2c82652b999411f8d9a3c3f3ec32ee5", "truncated": false}, "is_active": true}, {"id": "4d22e359-f3e1-55cb-8e8b-41b360c14178", "feature_slug": "tiers", "title": "System Flow Diagrams", "content": "### Primary User Journey Flow\n\n```mermaid\ngraph TD\n    A[👤 New User Signup] --> B[assign_entry_tier_on_signup]\n    B --> C[🥉 Bronze Tier Assigned]\n    C --> D[after_user_signup_tier_setup]\n    D --> E[📊 tier_progress Created]\n    D --> F[📝 tier_change_ledger Entry]\n    \n    G[💳 Purchase Completed] --> H[trigger_tier_eval_on_purchase]\n    I[💰 Points Earned] --> J[trigger_tier_eval_on_wallet]\n    \n    H --> K[safe_trigger_tier_eval]\n    J --> K\n    K --> L[queue_tier_evaluation]\n    \n    L --> M{Deduplication Check<br/>30 second window}\n    M -->|Already Queued| N[❌ Skip Silently]\n    M -->|New Request| O[📬 pgmq.send<br/>tier_evaluation_queue]\n    O --> P[tier_evaluation_tracking<br/>status = queued]\n    \n    Q[🕐 process-tier-queue<br/>Every 30 seconds] --> R[process_tier_evaluation_batch<br/>batch_size: 2000]\n    S[🕑 daily-tier-evaluation<br/>2 AM daily] --> T[Queue users with<br/>frequency = daily]\n    U[🗓️ monthly-tier-evaluation<br/>3 AM monthly] --> V[Queue users with<br/>frequency = monthly]\n    W[⏰ period-end-tier-evaluation<br/>4 AM daily] --> X[Queue users with<br/>deadlines today]\n    \n    T --> O\n    V --> O\n    X --> O\n    \n    R --> Y[pgmq.read messages]\n    Y --> Z[evaluate_user_tier_status<br/>🎯 CORE FUNCTION]\n    \n    Z --> AA[calculate_tier_metric_value<br/>🎯 CORE FUNCTION]\n    AA --> BB{Metric Type}\n    BB -->|points/tickets| CC[wallet_ledger<br/>transaction_type = earn]\n    BB -->|sales| DD[purchase_ledger<br/>credit/debit logic]\n    BB -->|orders| EE[purchase_ledger<br/>COUNT final_amount > 0]\n    \n    CC --> FF[calculate_tier_window_dates<br/>🎯 CORE FUNCTION]\n    DD --> FF\n    EE --> FF\n    FF --> GG{Window Type}\n    GG -->|rolling| HH[Last N months from today]\n    GG -->|fixed_period| II[Calendar periods MM-DD]\n    GG -->|anniversary| JJ[User signup anniversary]\n    \n    HH --> KK[🧠 Tier Decision Logic<br/>CAN SKIP TIERS]\n    II --> KK\n    JJ --> KK\n    \n    KK --> LL{Evaluation Result}\n    LL -->|upgrade| MM[🚀 HIGHEST qualified tier<br/>Can skip intermediate]\n    LL -->|downgrade| NN[⬇️ HIGHEST qualifying lower<br/>or entry tier]\n    LL -->|maintain| OO[➡️ Keep current tier]\n    LL -->|assign_entry| PP[🆕 Assign Bronze tier]\n    \n    MM --> QQ[ensure_tier_progress<br/>🎯 CORE FUNCTION]\n    NN --> QQ\n    OO --> QQ\n    PP --> QQ\n    \n    QQ --> RR{Tier Change Required?}\n    RR -->|Yes| SS[📝 tier_change_ledger INSERT]\n    RR -->|Yes| TT[🔄 user_accounts.tier_id UPDATE]\n    RR -->|No| UU[📊 tier_progress UPDATE only]\n    \n    SS --> VV[📦 pgmq.archive message]\n    TT --> VV\n    UU --> VV\n    \n    style A fill:#e3f2fd\n    style C fill:#8d6e63,color:#fff\n    style O fill:#f3e5f5\n    style Z fill:#e8f5e8\n    style QQ fill:#e1f5fe\n    style MM fill:#4caf50,color:#fff\n    style NN fill:#f44336,color:#fff\n    style OO fill:#ff9800,color:#fff\n    style PP fill:#2196f3,color:#fff\n```\n\n### Tier Progression Logic & Data Architecture\n\n```mermaid\ngraph LR\n    subgraph \"🏆 Tier Hierarchy - NON-ADJACENT PROGRESSION\"\n        T1[🥉 Bronze<br/>Entry Tier<br/>No Requirements]\n        T2[🥈 Silver<br/>500 pts/6mo OR 10 tickets/6mo<br/>300 pts/12mo maintain]\n        T3[🥇 Gold<br/>1500 pts/6mo OR 100k sales/6mo<br/>1000 pts/12mo maintain]\n        T4[💎 Platinum<br/>5000 pts/6mo OR 20 orders/6mo<br/>3000 pts/12mo maintain]\n        T5[💍 Diamond<br/>10000 pts/6mo OR 500k sales/12mo<br/>7500 pts/12mo maintain]\n        \n        T1 -.->|Can skip to| T3\n        T1 -.->|Can skip to| T4\n        T1 -.->|Can skip to| T5\n        T1 --> T2\n        T2 --> T3\n        T2 -.->|Can skip to| T4\n        T2 -.->|Can skip to| T5\n        T3 --> T4\n        T3 -.->|Can skip to| T5\n        T4 --> T5\n    end\n    \n    subgraph \"📊 Data Sources\"\n        DS1[wallet_ledger<br/>💰 Points/Tickets<br/>WHERE transaction_type = earn<br/>SUM amount]\n        DS2[purchase_ledger<br/>🛒 Sales: SUM final_amount<br/>📦 Orders: COUNT final_amount > 0<br/>Handles credit/debit records]\n        DS3[user_accounts<br/>👤 Current Tier Assignment<br/>🔒 Tier Lock Status<br/>📅 Anniversary Dates]\n    end\n    \n    subgraph \"⏰ Window Calculation Engine\"\n        W1[🔄 Rolling<br/>Last N months from today<br/>Dynamic evaluation period]\n        W2[📅 Fixed Period<br/>MM-DD format start dates<br/>Calendar-based periods]\n        W3[🎂 Anniversary<br/>User-specific periods<br/>Based on signup date]\n    end\n    \n    subgraph \"🧮 Core Evaluation Engine\"\n        E1[evaluate_user_tier_status<br/>🎯 CORE ORCHESTRATOR<br/>Master decision engine]\n        E2[calculate_tier_metrics_bulk<br/>🎯 CORE OPTIMIZER<br/>Batch processing engine]\n        E3[calculate_tier_metric_value<br/>🎯 CORE CALCULATOR<br/>Individual metric engine]\n        \n        E1 --> E3\n        E2 --> E3\n    end\n    \n    subgraph \"🔄 Processing Outcomes\"\n        P1[🚀 UPGRADE<br/>HIGHEST qualified tier<br/>Can skip intermediate tiers]\n        P2[⬇️ DOWNGRADE<br/>HIGHEST qualifying lower tier<br/>or entry tier fallback]\n        P3[➡️ MAINTAIN<br/>Keep current tier<br/>Update progress only]\n        P4[🆕 ASSIGN_ENTRY<br/>New user without tier<br/>Assign entry_tier = true]\n    end\n    \n    subgraph \"📬 Queue Infrastructure\"\n        Q1[🎯 tier_evaluation_queue<br/>Main processing queue<br/>Deduplication: 30 seconds<br/>Batch size: 2000]\n        Q2[⚡ Real-time Triggers<br/>• Purchase completed<br/>• Points earned<br/>• Tickets earned]\n        Q3[⏰ Scheduled Jobs<br/>• Daily evaluations<br/>• Monthly evaluations<br/>• Period-end checks]\n        \n        Q2 --> Q1\n        Q3 --> Q1\n    end\n    \n    DS1 --> E1\n    DS2 --> E1\n    DS3 --> E1\n    \n    W1 --> E3\n    W2 --> E3\n    W3 --> E3\n    \n    E1 --> P1\n    E1 --> P2\n    E1 --> P3\n    E1 --> P4\n    \n    subgraph \"💾 Output Tables\"\n        O1[tier_progress<br/>📈 Real-time progress<br/>upgrade_progress_percent<br/>maintain_progress]\n        O2[tier_change_ledger<br/>📝 Complete audit trail<br/>from_tier_id → to_tier_id<br/>change_type, metadata]\n        O3[tier_evaluation_tracking<br/>⚙️ Queue processing status<br/>last_queued_at<br/>processing_status]\n        O4[tier_evaluation_errors<br/>🚨 Error logging<br/>error_message<br/>context jsonb]\n    end\n    \n    P1 --> O1\n    P1 --> O2\n    P2 --> O1\n    P2 --> O2\n    P3 --> O1\n    P4 --> O1\n    P4 --> O2\n    \n    Q1 --> O3\n    Q1 --> O4\n    \n    style T1 fill:#8d6e63,color:#fff\n    style T2 fill:#9e9e9e,color:#fff\n    style T3 fill:#ffb300,color:#fff\n    style T4 fill:#e1bee7\n    style T5 fill:#b39ddb\n    \n    style DS1 fill:#e8f5e8\n    style DS2 fill:#e3f2fd\n    style DS3 fill:#fff3e0\n    \n    style P1 fill:#e1f5fe\n    style P2 fill:#ffebee\n    style P3 fill:#f9fbe7\n    style P4 fill:#f3e5f5\n    \n    style Q1 fill:#fce4ec\n    style E1 fill:#e0f2f1\n```\n\n### Key Concepts Glossary\n\n#### Transaction Types\n- **Earn**: Currency/points awarded to user (INCLUDED in tier evaluation)\n- **Burn**: Currency/points spent by user for rewards (EXCLUDED from tier evaluation)\n- **Reversal**: Correction/refund transaction (earn type with negative signed_amount, INCLUDED in tier evaluation)\n\n#### Currency Components\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Tier.md#L952 System Flow Diagrams", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "532de7aac502af772185cf5504a3fc5e8a8cfd7f44ba7f40f676c84412c5516b", "truncated": true}, "is_active": true}, {"id": "59c2e7f0-6b9c-5993-8bc3-6015c328a811", "feature_slug": "tiers", "title": "Tier Domain Reference", "content": "**Keywords:** tier, level, upgrade, downgrade, maintain, tier progress, tier conditions, ranking, entry tier, burn rate, point-to-discount, tier lock, window type, calendar month, calendar quarter, rolling, fixed period, anniversary, persona tier\n**Source:** `Tier.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `get_user_burn_rate()` | None (merchant + user from JWT) | JSON: `effective_rate`, `base_rate`, `multiplier`, `is_enabled`, `tier_name`, `available_points`, `max_discount`, `factors[]` | 621–674 |\n**Key Business Rules (summary):**\n- Users can skip tiers (non-adjacent progression) if they qualify for higher ones\n- Multiple upgrade paths per tier (points OR sales OR orders)\n- Progress tracking shows the best path automatically (highest `progress_percent`)\n- `burn_rate` on `tier_master` converts points to monetary discount (NULL = disabled)\n- Tier evaluation considers `user_type` (buyer/seller) and optional `tier_persona_assignments`; no assignment rows means all personas\n- Downgrade happens when maintain conditions fail; user drops to highest qualifying lower tier or entry tier\n- `tier_change_ledger` rows publish through CDC unless `skip_cdc = true`; AMP lifecycle automations can trigger on `change_type = upgrade` or `change_type = downgrade`; RLS allows admins to modify ledger rows and members to read their own rows\n- `tier_master` delete paths require leading indexes on all referencing FK columns, including global `user_accounts.tier_id` and chained ledger references such as `tier_change_ledger.triggered_by_condition_id`, to avoid statement timeouts during restrict/cascade checks", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/tier.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c0c4e9e24b7263eaa23c7febfbca60bd052ad4321d2729fd3467ed4a10ea2673", "truncated": false}, "is_active": true}, {"id": "8b2e8292-1650-51da-ab2f-2c41b07c39f1", "feature_slug": "tiers", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n\n| Config                                     | Expected behavior                                                              |\n| ------------------------------------------ | ------------------------------------------------------------------------------ |\n| Entry tier = true, ranking = 1             | New members auto-assigned to this tier on signup                               |\n| Upgrade: points >= 500, rolling 6 months   | Member with 500+ points in last 6 months qualifies for upgrade                 |\n| Upgrade: sales >= 10000 OR orders >= 50    | Meeting EITHER condition qualifies (OR logic between conditions)               |\n| Maintain: points >= 200, rolling 12 months | Member below 200 points when deadline arrives → downgrade                      |\n| No maintain conditions on tier             | Member stays in this tier indefinitely (no downgrade)                          |\n| `burn_rate = 0.5`                          | `get_user_burn_rate()` returns `effective_rate = 0.5`, `is_enabled = true`     |\n| `burn_rate = NULL`                         | `get_user_burn_rate()` returns `effective_rate = 0`, `is_enabled = false`      |\n| `persona_id` set on tier                   | Only members with matching persona are evaluated against this tier             |\n| Window type = `calendar_quarter`           | Window bounds align to Q1/Q2/Q3/Q4 regardless of when condition was created    |\n| Multiple tiers qualify for upgrade         | Member upgrades to highest-ranking qualifying tier (non-adjacent skip allowed) |\n\n\n**Business rules as assertions:**\n\n- ASSERT: On signup, member is assigned the entry tier for their user_type/persona\n- ASSERT: Upgrade evaluates highest-ranking tiers first; first qualifying tier wins\n- ASSERT: Members can skip tiers (e.g., Bronze → Platinum if they meet Platinum conditions)\n- ASSERT: Downgrade goes to highest qualifying lower tier, or entry tier if none qualify\n- ASSERT: Maintain conditions are only checked when `maintain_deadline <= evaluation_date`\n- ASSERT: Each tier change creates exactly one `tier_change_ledger` record\n- ASSERT: `tier_progress` always reflects the best single upgrade path (highest progress_percent)\n- ASSERT: `burn_rate` response includes `max_discount = available_points × effective_rate`\n\n**Change type values in `tier_change_ledger`:**\n\n\n| Value       | Meaning                                           |\n| ----------- | ------------------------------------------------- |\n| `initial`   | First tier assignment (signup)                    |\n| `upgrade`   | Automatic upgrade via condition evaluation        |\n| `downgrade` | Automatic downgrade when maintain conditions fail |\n| `manual`    | Admin-initiated tier change                       |\n| `scheduled` | Batch-processed tier change (pg_cron)             |\n\n\n**Evaluation architecture:**\n\n- Upgrades: triggered by CDC → Render consumer (real-time on qualifying transactions)\n- Maintains/downgrades: pg_cron batch processing in chunks of 1,000 users\n- Deduplication: 5-minute Redis window prevents duplicate evaluations", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/tiers.md#L189 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5170178e63b71ee8e7be769e4521f94123d4dddb0076555b83fe2e9d6518433d", "truncated": false}, "is_active": true}, {"id": "9a69b76b-31c9-58fe-882e-789eeb3cf9f9", "feature_slug": "tiers", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n\n| Page / Component            | Current route                      | Data source                                         |\n| --------------------------- | ---------------------------------- | --------------------------------------------------- |\n| Homepage Profile Card       | `/`                                | `get_user_tier_progress(user_id, merchant_id)`      |\n| Homepage tier progress pill | `/`                                | Same as Profile Card                                |\n| History drawer (Tier tab)   | Bottom-sheet from Homepage/Profile | `bff_get_tier_history(p_filter, p_limit, p_offset)` |\n| Burn rate at checkout       | Checkout flow                      | `get_user_burn_rate()`                              |\n\n\n### 5a. View Current Tier\n\n1. Member opens the app — **Profile Card** on homepage shows: tier name with gradient text (derived from tier color), points balance, and \"X points to [Next Tier]\" progress text\n2. Tier color drives the visual gradient: the system converts hex to HSL and generates light→dark gradient applied to the tier name text\n3. If the tier has an icon, it appears alongside the tier name\n\n### 5b. Track Upgrade Progress\n\n1. **Profile Card** shows progress toward next tier: \"/ 100 Points to Platinum\"\n2. Progress data comes from `tier_progress`: `upgrade_progress_percent`, `upgrade_metric_needed`, `upgrade_deadline`\n3. The system automatically picks the best upgrade path (highest `progress_percent`) when multiple conditions exist\n\n### 5c. View Tier History\n\n1. From Homepage or Profile, member opens **History drawer** → selects **Tier** filter\n2. Each entry shows: change title (e.g., \"Upgraded to Gold\"), from/to tier, change type, date\n3. Entries include tier icon and color for visual identification\n\n### 5d. Use Burn Rate at Checkout\n\n1. At checkout, the app calls `get_user_burn_rate()` to fetch the member''s current conversion rate\n2. Response includes: `effective_rate`, `base_rate`, `multiplier`, `is_enabled`, `tier_name`, `available_points`, `max_discount`\n3. If burn rate is enabled, member sees maximum discount they can apply (available_points × effective_rate)\n4. If tier has no burn rate configured, `is_enabled = false` and burn rate UI is hidden", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/tiers.md#L149 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ddc124cfee42aa8fb67b38bf41bb1769463ad432218f81e97838377324dab312", "truncated": false}, "is_active": true}, {"id": "06b9836a-5a48-59ee-a07f-829fc13d66b9", "feature_slug": "tiers", "title": "6b. For Marketing", "content": "**Value proposition**: Tiers give members a visible reason to stay engaged. The progression from Bronze to Silver to Gold creates a game-like experience — members can see exactly how close they are to the next level and what benefits they''ll unlock. For merchants, this translates to higher average order values as members chase the next tier.\n\n**Use-case stories:**\n\n1. **Café chain** — Three tiers: Bronze (entry), Silver (200 points in 6 months), Gold (500 points in 6 months). Gold members get burn_rate 0.5 (1 point = ฿0.50 off), Silver gets 0.25. Members actively buy more coffee to reach Gold before their window closes.\n2. **B2B distributor** — Persona-based ladders: \"Retailer\" persona has Bronze/Silver/Gold based on sales volume, \"Wholesaler\" persona has Standard/Premium based on order count. Each persona sees only their relevant tier ladder.\n3. **Fashion retailer** — Uses `calendar_quarter` window type to align tier evaluation with seasonal buying patterns. Members must spend ฿5,000 per quarter to maintain Gold. Creates quarterly spending urgency.\n4. **Anniversary rewards** — Uses `anniversary` window type so each member''s tier resets on their personal signup anniversary. More equitable than calendar-based windows for members who join mid-year.\n\n**Metrics merchants care about**: Tier distribution (% of members at each level), upgrade rate, downgrade rate, average spend per tier, tier-driven revenue lift.", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/tiers.md#L189 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2c979fab92af2f473eeeaf910636ccbac5420eeb24b2c3130f094c3026248bdf", "truncated": false}, "is_active": true}, {"id": "d1c0027a-7a48-553a-a51a-d5f87caabcf3", "feature_slug": "translation-system", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page Name | Current Route | BFF / Data Source |\n|---|---|---|\n| Translation Manager | `/translation` | `translation_api(p_action, p_params)` |\n| Global Settings | `/merchant-global-settings` | `bff_get_merchant_global_settings()` |\n\n### 4a. Manage Entity Translations\n\n1. Open **Translation Manager** — 3-panel layout: category nav (left), entity list (center), translation grid (right)\n2. Left panel shows entity type groups (sections like \"Content\", \"Forms\", etc.) — select an entity type (e.g., \"Rewards\")\n3. Center panel loads all entities of that type — select a specific entity (e.g., \"Coffee Mug\")\n4. Right panel shows the translation grid: rows = translatable fields, columns = EN, TH, ZH, JA\n5. Edit any cell to add or change a translation. Edited rows show an \"Edited\" badge. Header shows \"Unsaved changes\" badge.\n6. Optionally click **\"AI Translate\"** to auto-fill empty translations using AI — fills all language columns based on the English reference\n7. Click **\"Save\"** to persist all changes. Toast confirms \"Translations saved\".\n\n### 4b. Configure Merchant Languages\n\n1. Open **Global Settings** — language configuration is part of the merchant setup\n2. Enable/disable languages, set default language, configure display order\n3. Save changes — clears merchant config cache\n\n### 4c. Manage Static UI Translations\n\nStatic UI translations (button labels, page headers, error messages) are managed directly in the database, not through the Translation Manager UI. Admin dashboard text lives in `ui_translation_admin`; member-facing text lives in `ui_translations`.\n\nCurrent member-facing page keys with translation coverage:\n\n| Page Key | Field Count | Coverage |\n|---|---|---|\n| `signup_form` | 27 | Auth, OTP, consent, navigation, errors |\n| `rewards` | 26 | Catalog headers, detail view, popups, filters |\n| `redemption_status` | 5 | Status labels (used, redeemed, expired, cancelled, pending) |\n| `profile` | ~15 | Profile header, settings menu, drawers |\n| `navigation` | ~5 | Bottom nav labels |\n| `utility` | ~10 | Shared buttons (Save, Cancel, Edit) |\n| `history` | ~8 | History drawer filters and labels |\n| `missions` | ~5 | Mission page elements |\n| `benefits` | ~5 | Tier info drawer |\n\n### 4d. Common Admin Mistakes\n\n- Forgetting to add translations for a new language after enabling it → members see fallback text\n- Changing the default language without clearing caches → stale data for up to 30 minutes\n- Adding UI translations to `ui_translations` when the target is the admin dashboard (should use `ui_translation_admin`)\n- Editing entity master table content without updating translations → languages drift apart\n- Adding a new UI page without creating translations for all 4 languages → partial page rendering", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/translation-system.md#L75 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "747125d91ce2eab195897e3e53ce1e3fee4cd289871e8c525171f8b47a0b8fa2", "truncated": false}, "is_active": true}, {"id": "15522f67-e5f9-5867-9c07-2209c636f6b5", "feature_slug": "translation-system", "title": "7. Business Rules", "content": "**Rule:** Master table content is labeled with the merchant''s default language, not hardcoded as English.\n**Example:** A Thai-first merchant''s `reward_master.name` = \"แก้วกาแฟ\" is cached under `th`, not `en`. English is stored in the `translations` table.\n\n**Rule:** All languages are stored in a single cache key per entity/domain. Language extraction happens at request time via JSONB operations.\n**Example:** One Redis key holds `{\"en\": {...}, \"th\": {...}, \"ja\": {...}}`. Requesting Thai extracts only the `th` object.\n\n**Rule:** Cache invalidation triggers automatically on table changes (via DB triggers), but stale reads are possible within the TTL window.\n**Example:** Admin edits a reward name → trigger fires → rewards cache invalidated → next member request rebuilds. But a member who loaded 1 minute ago still sees old data until their cache entry expires.\n\n**Rule:** UI translations are public endpoints (no auth required) because they serve login and signup pages.\n**Example:** `get_ui_translations` is callable by anonymous users to render the signup form in the member''s language.\n\n**Rule:** Admin and member UI translations are stored in separate tables with separate API functions.\n**Example:** Admin dashboard uses `ui_translation_admin` + `get_admin_ui_translations()`. Member app uses `ui_translations` + `get_ui_translations()`.\n\n**Rule:** The `translation_api` BFF function handles all admin translation operations through a single endpoint with action routing (`get_menu`, `get_entities`, `get_form`, `save`).\n**Example:** Admin selects \"Rewards\" in nav → `translation_api(action=''get_entities'', params={entity_type: ''reward''})` returns the list.\n\n**Rule:** Entity translations are keyed by the composite of `entity_type` + `entity_id` + `field_name` + `language_code`. This combination is unique-constrained — one translation per field per language per entity.\n**Example:** Reward \"Coffee Mug\" (`id: abc123`) can have exactly one Thai translation for `name`. Inserting a second one violates the unique constraint — use upsert.\n\n**Rule:** The member app loads all UI translations once at app initialization (server-side in the root layout), not per-page. Language switching triggers a full server re-render that re-fetches all translations.\n**Example:** Switching from Thai to English calls `get_ui_translations(null, ''en'')` → receives all pages → entire app re-renders.\n\n**Rule:** Legacy local i18n dictionaries exist for wallet and earn modules (`wallet-i18n.ts`, `earn-i18n.ts`). These operate independently of the centralized DB-backed system and will be migrated in the future.\n**Example:** Wallet drawer translations come from a hardcoded TypeScript dictionary, not from `get_ui_translations`.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/translation-system.md#L231 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d955fd9f6e61afb3232ec8c2de26d1acd0fd1ba4fb6720a54a65e44ec1ab44a3", "truncated": false}, "is_active": true}, {"id": "ba4a6046-23ea-5d3a-b06e-7f76ddd77b7e", "feature_slug": "translation-system", "title": "3. Configuration Reference", "content": "### Merchant Language Setup (`merchant_languages` table)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| language_code | Which language is available | `th` | Required |\n| language_name | Display name shown to members | \"ไทย\" | Required |\n| is_default | Whether this is the merchant''s primary language | true | false |\n| is_active | Whether members can select this language | true | true |\n| display_order | Sort order in language picker | 1 | 0 |\n\n### Entity Translation Fields\n\n| Entity Type | Source Table | Translatable Fields |\n|---|---|---|\n| `reward` | `reward_master` | name, description_headline, description_body, description_tc, description_slip |\n| `reward_category` | `reward_category` | name |\n| `form_field` | `form_fields` | label, placeholder, help_text |\n| `form_field_option` | `form_field_options` | option_label |\n| `form_field_group` | `form_field_groups` | group_name |\n| `user_field_config` | `user_field_config` | label, placeholder, help_text |\n| `persona` | `persona_master` | persona_name, group_name |\n| `consent_version` | `consent_versions` | title, preview, content |\n| `communication_topic` | `communication_topics` | topic_name |\n| `tier` | `tier_master` | tier_name |\n\n### Cache TTLs\n\n| Cache Domain | TTL | Redis Database |\n|---|---|---|\n| Rewards catalog | 5 minutes | supabase-rewards-cache |\n| User profile template | 5 minutes | supabase-user-profile-cache |\n| UI translations (member) | 1 hour | supabase-ui-translations |\n| Merchant config | 30 minutes | crm-merchant-config-cache |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/translation-system.md#L39 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f830624ac6988273386951422b5aad4c9986f28d22a452154be24f57da36065b", "truncated": false}, "is_active": true}, {"id": "007cdb6c-fc76-58f4-8735-ebb92a4a902f", "feature_slug": "translation-system", "title": "Database Schema Reference", "content": "### `translations` Table\n\n```sql\nCREATE TABLE translations (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    merchant_id UUID NOT NULL,\n    entity_type TEXT NOT NULL,\n    entity_id UUID NOT NULL,\n    field_name TEXT NOT NULL,\n    language_code TEXT NOT NULL,\n    translated_value TEXT NOT NULL,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    \n    UNIQUE(entity_type, entity_id, field_name, language_code)\n);\n```\n\n---\n\n### `ui_translations` Table\n\n```sql\nCREATE TABLE ui_translations (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    merchant_id UUID DEFAULT NULL,\n    page_key TEXT NOT NULL,\n    field_key TEXT NOT NULL,\n    language_code TEXT NOT NULL,\n    translated_value TEXT NOT NULL,\n    category TEXT,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    \n    UNIQUE(merchant_id, page_key, field_key, language_code)\n);\n```\n\n---\n\n### `merchant_languages` Table\n\n```sql\nCREATE TABLE merchant_languages (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    merchant_id UUID NOT NULL,\n    language_code TEXT NOT NULL,\n    language_name TEXT NOT NULL,\n    is_default BOOLEAN DEFAULT false,\n    is_active BOOLEAN DEFAULT true,\n    display_order INTEGER DEFAULT 0,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    \n    UNIQUE(merchant_id, language_code)\n);\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Translation_System.md#L1138 Database Schema Reference", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "453fb72524749de8a38763fb652b0c1d1c63af9a1a34e6c6bd873f042df5ed3d", "truncated": false}, "is_active": true}, {"id": "df3f0d24-cf09-5b70-b044-93481f33fe37", "feature_slug": "translation-system", "title": "Table of Contents", "content": "- [Architecture Overview](#architecture-overview)\n- [Dynamic Entity Translations](#dynamic-entity-translations)\n- [Static UI Translations](#static-ui-translations)\n- [Cache Architecture](#cache-architecture)\n- [Merchant Language Configuration](#merchant-language-configuration)\n- [API Reference](#api-reference)\n- [Adding New Translations](#adding-new-translations)\n- [Best Practices](#best-practices)\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Translation_System.md#L18 Table of Contents", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b44e296fad1ee504e0aeb33b1b1a499de094ed048ca50d60e25025509ef4cbf5", "truncated": false}, "is_active": true}, {"id": "5d6f7398-1315-59bd-9743-48d766ba2493", "feature_slug": "translation-system", "title": "2. Key Concepts", "content": "**Entity Translation** — A translated value for a specific database record''s field. Stored in the `translations` table, keyed by `entity_type` + `entity_id` + `field_name` + `language_code`. Example: the reward \"Coffee Mug\" has an entity translation for Thai: `name` = \"แก้วกาแฟ\".\n\n**UI Translation** — A translated string for static interface text not tied to any entity. Stored in the `ui_translations` table (member-facing) or `ui_translation_admin` table (admin dashboard), keyed by `page_key` + `field_key` + `language_code`. Example: the rewards page header `header_page_title` = \"รายการของรางวัล\" in Thai.\n\n**Fallback Chain** — The resolution order when a translation is missing: requested language → merchant default language → English → raw base value. Applied both server-side (in DB functions) and client-side (in the `useTranslation` hook).\n\n**Supported Languages** — Four language codes: `en` (English), `th` (Thai), `ja` (Japanese), `zh` (Chinese).\n\n**Default Language** — The merchant''s primary language, set in `merchant_languages` with `is_default = true`. Master table content (e.g., `reward_master.name`) is assumed to be in this language. One default per merchant.\n\n**Language Code** — Two-letter identifier (`en`, `th`, `ja`, `zh`) used throughout as the key for translations.\n\n**Entity Type** — The category of translatable content. Current types: `reward`, `reward_category`, `form_field`, `form_field_option`, `form_field_group`, `user_field_config`, `persona`, `consent_version`, `communication_topic`, `tier`.\n\n**Page Key** — Groups static UI translations by screen. Examples: `signup_form`, `rewards`, `profile`, `history`, `navigation`, `utility`, `redemption_status`.\n\n**Field Key** — Identifies a specific UI string within a page. Uses section prefixes: `header_`, `list_`, `details_`, `filter_`, `popup_`, `button_`, `text_`, `error_`, `status_`.\n\n**Merchant Override** — A UI translation scoped to a specific merchant (non-null `merchant_id`), which takes priority over the global version (null `merchant_id`). Example: Syngenta overrides the signup page title with their brand name.\n\n**Language Cookie** — Browser cookie `loyalty_language` set when a member explicitly switches language. Persists for 1 year. Takes highest priority in language resolution.\n\n**Translation Grid** — The admin UI component showing translatable fields as rows and languages as columns (EN, TH, ZH, JA). All cells are editable. Located in the right panel of the Translation Manager.\n\n**AI Translate** — Admin feature that auto-fills missing translations using AI. Triggered by the \"AI Translate\" button in the Translation Grid toolbar. Sends current rows to `/api/translation/ai-translate` and receives suggested translations.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/translation-system.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ba611dea18d5807230c02bdd1ae0f8d65553c1eed6ba9edb2056ec1d7904c92c", "truncated": false}, "is_active": true}, {"id": "fc469cc8-3200-5413-9bf4-e851415fa14a", "feature_slug": "translation-system", "title": "6a. For Customer Success / Support", "content": "**Top questions:**\n\n| Question | Answer |\n|---|---|\n| \"Member sees English text on a Thai app\" | Translation missing for that field in Thai — falls back to merchant default, then English. Add the missing translation via Translation Manager. |\n| \"Language changed but text didn''t update\" | Redis cache may be stale. UI translations cache is 1 hour, rewards 5 minutes. Clear cache or wait for expiry. Member can also hard-refresh the app. |\n| \"Member can''t find language option\" | Language must be enabled in `merchant_languages` with `is_active = true`. Check Global Settings. |\n| \"Some text is translated, some isn''t\" | Entity translations and UI translations are independent. An entity may be translated while the surrounding UI buttons are not, or vice versa. |\n| \"Admin dashboard shows wrong language\" | Admin uses a separate translation table (`ui_translation_admin`). Check that translations exist there. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/translation-system.md#L163 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "fd4df3cfe78207394004a95628221d1ab5f0284120b759a2c2d48d2d8983adb7", "truncated": false}, "is_active": true}, {"id": "243e0df5-33e3-585f-87eb-75d72830e079", "feature_slug": "translation-system", "title": "1. Overview", "content": "The Translation System provides multi-language support across the entire loyalty platform. It handles two distinct categories of text: dynamic content tied to specific entities (reward names, form field labels, persona names) and static UI text (page headers, button labels, error messages). Together, they let merchants operate loyalty programs in up to four languages — English, Thai, Japanese, and Chinese — with each merchant choosing their own default.\n\nWhen a member opens the app, the system resolves their preferred language from a cookie, falls back to the browser''s Accept-Language header, and ultimately defaults to Thai. All translated text loads in a single API call at app initialization. If a translation is missing for the requested language, a fallback chain kicks in: try the merchant''s default language, then English, then the raw base value. This means members never see blank fields — they always get the best available text.\n\nFor merchants expanding into new markets, the admin dashboard provides a dedicated Translation page where staff can browse every translatable entity, edit translations in a 4-column grid (one per language), and use AI-assisted translation to fill gaps. Entity translations are also managed inline within entity forms (e.g., reward settings). The entire system is backed by Redis caching with domain-isolated databases, keeping response times under 100ms.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/translation-system.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4634073494630e2c8a2bb609336d63a1252b79cb6304162c204ad979abb13437", "truncated": false}, "is_active": true}, {"id": "b02404ac-3553-5335-b6a2-85d22ca74c09", "feature_slug": "translation-system", "title": "8. Related Features", "content": "| Feature | Connection to Translation |\n|---|---|\n| Rewards | Reward name, headline, body, T&C, and slip are translatable entity fields. Catalog API accepts `p_language`. See `Reward.md`. |\n| Forms | Form field labels, placeholders, help text, and option labels are translatable. Profile template API accepts `p_language`. See `Forms.md`. |\n| Tag & Persona | Persona names and group names are translatable. See `Tag_and_Persona.md`. |\n| Tier | Tier names are translatable entity fields. See `Tier.md`. |\n| Consent | Consent version title, preview, and content are translatable. See PDPA/consent docs. |\n| Currency | Communication topic names are translatable. See `Currency.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/translation-system.md#L260 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "0ee0a28ae14ea5c1b75bb3764441bd681f4f3ea92a2838d40e0858b0d7741824", "truncated": false}, "is_active": true}, {"id": "83a10e56-d9c1-56b9-8f91-561d7f4bcd54", "feature_slug": "translation-system", "title": "Architecture Overview", "content": "### Two Translation Systems\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│ TRANSLATION SYSTEM                                          │\n├─────────────────────────────────────────────────────────────┤\n│                                                             │\n│  ┌──────────────────────────────┐  ┌────────────────────┐ │\n│  │ DYNAMIC TRANSLATIONS         │  │ STATIC UI TEXT     │ │\n│  │ (Entity-based)               │  │ (Page-based)       │ │\n│  ├──────────────────────────────┤  ├────────────────────┤ │\n│  │ • Rewards                    │  │ • Page titles      │ │\n│  │ • Form fields                │  │ • Buttons          │ │\n│  │ • Personas                   │  │ • Error messages   │ │\n│  │ • Consent versions           │  │ • Dialog text      │ │\n│  │ • Categories                 │  │ • Labels           │ │\n│  │                              │  │                    │ │\n│  │ Table: translations          │  │ Table: ui_trans... │ │\n│  │ Cache: Per feature           │  │ Cache: Isolated    │ │\n│  └──────────────────────────────┘  └────────────────────┘ │\n│                                                             │\n└─────────────────────────────────────────────────────────────┘\n```\n\n### Database Tables\n\n**1. `translations` (Dynamic Content)**\n```sql\n├─ entity_type: ''reward'', ''form_field'', ''persona'', ''consent_version''\n├─ entity_id: UUID of the entity\n├─ field_name: ''name'', ''description_headline'', ''label'', etc.\n├─ language_code: ''en'', ''th'', ''ja'', ''zh''\n├─ translated_value: The translated text\n└─ merchant_id: UUID (merchant-specific)\n```\n\n**2. `ui_translations` (Static UI Text)**\n```sql\n├─ page_key: ''signup_form'', ''rewards'', ''profile_edit''\n├─ field_key: ''header_page_title'', ''popup_button_confirm''\n├─ language_code: ''en'', ''th'', ''ja'', ''zh''\n├─ translated_value: The translated text\n├─ merchant_id: NULL (global) or UUID (merchant override)\n└─ category: ''button'', ''label'', ''error'', ''message'', ''title''\n```\n\n**3. `merchant_languages` (Configuration)**\n```sql\n├─ merchant_id: UUID\n├─ language_code: ''en'', ''th'', ''ja'', ''zh''\n├─ language_name: ''English'', ''ไทย'', ''日本語'', ''中文''\n├─ is_default: BOOLEAN (one per merchant)\n├─ is_active: BOOLEAN\n└─ display_order: INTEGER\n```\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Translation_System.md#L31 Architecture Overview", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7c96b2f8623036aabd9285826dab9af757c82262954110b2359f38d517b1818d", "truncated": false}, "is_active": true}, {"id": "deb6344e-8926-58dc-a47b-b893126596bf", "feature_slug": "translation-system", "title": "Cache Architecture", "content": "### Isolated Redis Databases\n\nEach translation domain uses its own dedicated Upstash Redis database for complete isolation:\n\n```\nUpstash Databases (4 Isolated):\n\n1. supabase-rewards-cache (mutual-stud-37574)\n   └─ merchant:X:rewards:all_languages\n   └─ Purpose: Rewards catalog with translations\n   └─ TTL: 5 minutes\n\n2. supabase-user-profile-cache (crisp-bison-32725)\n   └─ merchant:X:user_profile_template:all_languages\n   └─ Purpose: Form fields, personas, consent\n   └─ TTL: 5 minutes\n\n3. crm-merchant-config-cache (sweet-cardinal-5243)\n   └─ merchant:config:{merchant_code}\n   └─ Purpose: Merchant settings, default language\n   └─ TTL: 30 minutes\n\n4. supabase-ui-translations (free-hound-25865)\n   └─ ui:{page_key}:lang:{language}\n   └─ ui:all_pages:lang:{language}\n   └─ Purpose: Static UI text\n   └─ TTL: 1 hour\n```\n\n### Why Isolation?\n\n**Benefits:**\n1. ✅ Bug in one domain doesn''t affect others\n2. ✅ Independent monitoring and cost tracking\n3. ✅ Can flush one cache without affecting others\n4. ✅ Different TTLs per use case\n5. ✅ Clear ownership and separation of concerns\n\n**Before (Coupled):**\n```\nAll caches in one database → Change to UI breaks rewards ❌\n```\n\n**After (Isolated):**\n```\nEach cache in own database → UI changes isolated ✅\n```\n\n### Cache Invalidation\n\n**Dynamic Translations:**\n- Automatic triggers on entity changes (reward_master, translations table)\n- Example: Edit reward → cache invalidates → next request rebuilds\n\n**Static UI Translations:**\n- Automatic trigger on ui_translations table changes\n- Example: Update button text → all language caches clear\n\n**Merchant Config:**\n- Automatic trigger on merchant_master or merchant_languages changes\n- Example: Change default language → config cache clears\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Translation_System.md#L400 Cache Architecture", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "feaccd672411d94199ab6a754336a3d3c78e097d83c5f4fd3eaa011b98b1f894", "truncated": false}, "is_active": true}, {"id": "ca7f145a-6e50-5092-8ed4-8c70fc20f508", "feature_slug": "translation-system", "title": "Translation Domain Reference", "content": "**Keywords:** translation, language, i18n, multi-language, Thai, English, Japanese, Chinese, ui translation, entity translation, default language, fallback\n**Source:** `Translation_System.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `bff_get_user_profile_template(p_language, ...)` | `p_language` | Template with translated labels in requested language | (Forms.md) |\n| `api_get_rewards_full_cached()` | None | Rewards with all language translations embedded | (Reward.md) |\n**Key Business Rules (summary):**\n- Dynamic translations cover rewards, form fields, personas, consent versions\n- Static UI translations cover page titles, buttons, error messages, labels\n- Merchant-specific default language; automatic fallback chain\n- Redis cached per domain (isolated caches); 5-min TTL\n- All languages returned in single response for instant client-side language switching", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/translation.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8d15badd7ff337ebc5cb0fb33885033152029b11b081b02ca2a37c84679cebfb", "truncated": false}, "is_active": true}, {"id": "3dcf1c9d-dbf6-508f-bad8-f534c51dc548", "feature_slug": "translation-system", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected Behavior |\n|---|---|\n| Member requests `ja`, translation exists | Japanese text displayed |\n| Member requests `ja`, no Japanese translation, merchant default is `th` | Thai text displayed (fallback) |\n| Member requests `ja`, no Japanese, no Thai | English text displayed (final fallback) |\n| `merchant_languages` has `ja` with `is_active = false` | Japanese not shown in Change Language drawer |\n| UI translation has merchant-specific override | Override takes priority over global translation |\n| Entity saved with new name, cache not expired | Old name shown until cache expires (5 min for rewards) |\n| Cache cleared via invalidation function | Next request rebuilds cache with fresh data |\n\n**Business rules as assertions:**\n\n- ASSERT: Language resolution order is cookie → Accept-Language → `\"th\"` default\n- ASSERT: Fallback chain is requested → merchant default → English → base value\n- ASSERT: `get_ui_translations(null, lang)` returns all page keys in one response\n- ASSERT: Language cookie `loyalty_language` persists for 1 year\n- ASSERT: `router.refresh()` after language switch triggers full server re-render with new translations\n- ASSERT: AI Translate fills empty cells without overwriting existing translations\n- ASSERT: Save on Translation Manager only persists rows with changes\n- ASSERT: Merchant override (non-null `merchant_id`) takes priority over global (null `merchant_id`) in UI translations\n- ASSERT: Each Redis cache domain is isolated — flushing UI translations cache does not affect rewards cache\n\n**Error states to test:**\n\n- Request unsupported language code (e.g., `fr`) → should fall back to merchant default\n- `useTranslation` with nonexistent page key → returns field key strings as-is\n- `useTranslation` with nonexistent field key → returns the raw field key (e.g., `\"header_page_title\"`) or provided fallback string\n- AI Translate endpoint fails → error toast, existing translations preserved\n- Save with no changes → Save button disabled (not clickable)\n\n**Cross-feature test scenarios:**\n\n- Switch language to Japanese → rewards catalog shows Japanese names (entity translation) + Japanese UI labels (UI translation)\n- Create new reward → open Translation Manager → new reward appears in entity list → add translations → verify in member app\n- Change merchant default language → clear caches → verify fallback chain uses new default\n- Wallet and earn modules use local i18n dictionaries (legacy) — not affected by DB translation changes\n- Signup flow in Thai → all form field labels, error messages, consent text, and buttons appear in Thai\n- Redemption slip displays translated reward name, status label, and action buttons in member''s language", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/translation-system.md#L163 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "translation-system", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "943d67790042773aac9c76a7c187b871018238172c98924093be49c51fd78534", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
